	// changes

	preloadmenu: function() {
		var selectVal = document.getElementById('selectRoleVal').value;
		var selectText = document.getElementById('selectRoleVal').innerText;
		controller.loadInitialMenuOnRoleChange(selectVal, selectText);
	},
	loadSelect: function(selectArr, id, name, selectedVal) {
		try {
			selectArr.sort((a, b) => {
				try {
					let fa = a.name.toLowerCase(),
						fb = b.name.toLowerCase();
					if (fa < fb) {
						return -1;
					}
					if (fa > fb) {
						return 1;
					}
					return 0;
				} catch (error) {
					let fa = a.username.toLowerCase(),
						fb = b.username.toLowerCase();
					if (fa < fb) {
						return -1;
					}
					if (fa > fb) {
						return 1;
					}
					return 0;
				}
			});
			var option = '';
			for (var j = 0; j < selectArr.length; j++) {
				var itemO = selectArr[j];
				if (selectedVal == itemO[id]) {
					option += '<option selected value=' + itemO[id] + '>' + itemO[name] + '</option>';
				} else {
					option += '<option value=' + itemO[id] + '>' + itemO[name] + '</option>';
				}
			}
			return option;
		} catch (error) {}
	},
	loadActivities: function() {
		var listUrl = serverURL + 'workflowActivity/getWorkFlowActivityByUser?user_id=' + userObj.id;
		$.ajax({
			url: listUrl,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			success: function(data) {
				var jsonData = data;
				var counterActivities = jsonData.length;
				if (counterActivities != null && counterActivities != 'null') {
					var alertHtml = "<span class='alertNoMsg'>" + counterActivities + '</span>';
					$('.alertNo').html(alertHtml);
				}
				localStorage.setItem('alertNo', counterActivities);
			},
			fail: function() {
				$('#blinder').hide();
			},
			error: function(XMLHttpRequest, textStatus, errorThrown) {
				$('#blinder').hide();
			}
		});
	},
	UrlExists: function(url) {
		var http = new XMLHttpRequest();
		http.open('HEAD', url, false);
		http.send();
		return http.status != 404;
	},
	about: function(ctx) {},
	error: function(ctx) {
		window.location = 'index.html';
	},
	contact: function(ctx) {},
	getSecondPart: function(str) {
		hashArray = str.split('#');
		str = hashArray[1];
		if (str != undefined) {
			var res = str.split('/');
			return res[0];
		} else {
			return false;
		}
	},
	getThirdPart: function(str) {
		str = str.split('#')[1];
		var res = str.split('/');
		return res[1];
	},
	getFourthPart: function(str) {
		str = str.split('#')[2];
		var res = str.split('/');
		return res[2];
	},
	loadToolBarMenu: function(accessArr, org) {
		var toolBarMenu = '';
		var sideMenu = '';
		var count = 0;
		toolBarMenu +=
			"<div class='column' style='width:33%!important;'><h4 class='ui header'>Section</h4><div class='ui link list'>";
		for (key in accessArr) {
			count++;
			if (count == 9) {
				count = 0;
				toolBarMenu +=
					"</div></div><div class='column' style='width:33%!important;'><h4 class='ui header'>Section</h4><div class='ui link list'>";
			}
			if (org == 'Admin') {
				toolBarMenu +=
					"<a style='color:#333!important;word-wrap: break-word;white-space: initial' class='item' href='./#" +
					org +
					'/' +
					accessArr[key].identifier +
					"'></i>" +
					accessArr[key].windowName +
					'</a>';
			} else {
				toolBarMenu +=
					"<a style='color:#333!important;word-wrap: break-word;white-space: initial' class='item' href='./#" +
					org +
					'/' +
					accessArr[key].identifier +
					"-listing'></i>" +
					accessArr[key].windowName +
					'</a>';
			}
		}
		$('.menu-dropdown').html(toolBarMenu);
	},
