	cancelPhyto: function(data, reason) {
		console.log('phyto data', data);
		console.log('phyto data', data.documentNumber);

		//re-export - 657
		//phyto - 851

		var url = serverURL + 'ephyto/cancel/envelope';
		// var url = serverURL + "exporterConsignment/cancelePhyoCertificate?recordId=" + data.exporterConsignmentID + "&fromCountry=" + data.countryOfOrigin.code + "&toCountry=" + data.countryOfDestination.code + "&certificateType=851&nppoCertificateNumber=" + data.documentNumber;

		var formData = {
			recordId: data.exporterConsignmentID,
			fromCountry: data.countryOfOrigin.code,
			toCountry: data.countryOfDestination.code,
			certificateType: '851',
			nppoCertificateNumber: data.documentNumber
		};

		var formjson = JSON.stringify(formData);

		// var url  =   serverURL+ "exporterConsignment/cancelePhyoCertificate?recordId="+data.exporterConsignmentID+"&fromCountry=ET&toCountry=NL&certificateType=851&nppoCertificateNumber=701691/EXP/PIF/2025";
		// var exporterConsignmentID = data.exporterConsignmentID;
		// var url = serverURL + "exporterConsignment/cancelPhyoCertificate?exporterConsignmentID=" + exporterConsignmentID + "&reason=" + reason;
		$.ajax({
			url: url,
			contentType: 'application/json',
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			data: formjson,
			type: 'post',
			success: function(data) {
				console.log('data', data);

				if (data.status == 200) {
					controller.showToastMsg('Phyto Canceled', '#1a5589');
					controller.refreshCrudTables('cancelPhyto');
				} else if (data.status == 400) {
					controller.showToastMsg('Cancellation Failed', '#ff6666');
					controller.refreshCrudTables('cancelPhyto');
				} else if (data.status == 500) {
					controller.showToastMsg('Cancellation Failed', '#ff6666');
					controller.refreshCrudTables('cancelPhyto');
				} else {
					controller.showToastMsg('Cancellation Failed', '#ff6666');
					controller.refreshCrudTables('cancelPhyto');
				}

				// setTimeout(function () {
				//     window.location.reload()
				// }, 1000);
			},
			fail: function(e) {
				controller.showToastMsg('Cancellation Failed', '#ff6666');
			},
			error: function(XMLHttpRequest, textStatus, errorThrown) {
				controller.showToastMsg('Cancellation Failed', '#ff6666');
			}
		});
	},
