	formatDateFilter: function(date) {
		var d = new Date(date),
			month = '' + (d.getMonth() + 1),
			day = '' + d.getDate(),
			year = d.getFullYear();
		if (month.length < 2) month = '0' + month;
		if (day.length < 2) day = '0' + day;
		return [ year, month, day ].join('-');
	},
	savePasswordEntity: function() {
		var url = '';
		var formJson = $('#password-form-setup').serializeObject();
		if (formJson.passwordForm_users_id == '') {
			alert('Cannot Edit. User not identified');
			return false;
		} else {
			url = editPasswordUrl;
			formJson['users_id'] = $('#passwordForm_users_id').val();
			delete formJson.passwordForm_users_id;
			formJson['email'] = $('#passwordForm_Email').val();
			delete formJson.passwordForm_Email;
			formJson['oldPassword'] = $('#passwordForm_oldPassword').val();
			delete formJson.passwordForm_oldPassword;
			formJson['newPassword'] = $('#passwordForm_newPassword').val();
			delete formJson.passwordForm_newPassword;
		}
		var formData = JSON.stringify(formJson);
		crud.saveFormDetails(formData, url, function(output) {
			$('.ui.basic.modal.change_password').modal('hide');
		});
	},
