	uploadOtherDocuments: function(formData, name, description, recordID, tableregisterID) {
		var url =
			serverURL +
			'globalDocument/addGlobalDocument?recordId=' +
			recordID +
			'&name=' +
			name +
			'&tableRegisterId=' +
			tableregisterID +
			'&description=' +
			description +
			'&documentUploadType_id=0';
		var async_status = true;
		$.ajax({
			url: url,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			type: 'post',
			data: formData,
			processData: false,
			contentType: false,
			success: function(data, textStatus, xhr) {
				if (xhr.status == 200) {
					$.trim($('#name_value').val(''));
					$.trim($('#description_value').val(''));
					$.trim($('#filename').val(''));

					$('.reportAttachmentUpload').modal('hide');
					$('#confirmUploadBtn').html('Confirm Upload');
					$('#confirmUploadBtn').prop('disabled', false); //true|disabled will work on all
					controller.showToastMsg('Document Uploaded Successfully', '#1a5589');
					loadotherdocuments(recordID);
				}
			},
			fail: function(xhr, textStatus) {
				controller.showToastMsg('Document Upload Failed, Try again', '#ff6666');
				$('#confirmUploadBtn').html('Confirm Upload');
				$('#confirmUploadBtn').prop('disabled', false); //true|disabled will work on all
			},
			error: function(xhr, textStatus) {
				controller.showToastMsg('Document Upload Failed, Try again', '#ff6666');
				$('#confirmUploadBtn').html('Confirm Upload');
				$('#confirmUploadBtn').prop('disabled', false); //true|disabled will work on all
			}
		});
	},







	
