	clearCache: function() {
		if (window.history.replaceState) {
			window.history.replaceState(null, null, window.location.href);
		}

		// Clear the cache in the background
		if ('caches' in window) {
			caches
				.open('my-cache')
				.then((cache) => {
					return cache.keys().then((keys) => {
						keys.forEach((key) => {
							cache.delete(key);
						});
					});
				})
				.then(() => {})
				.catch((error) => {});
		}
	},
