	deactivate: function(user, admreason) {
		var url = serverURL + 'users/deleteUser?reason=' + admreason + '&users_id=' + user.users_id + '';
		var formData = {
			admreason: 'admreason'
		};
		var async_status = true;
		controller.activatedeactivateUserPostrequest(url, formData, async_status, function(data, status) {
			controller.refreshCrudTables();
			controller.showToastMsg('' + user.firstName + ' Deactivated', '#1a5589');
		});
	},
	addExporterDetails: function(
		name,
		email,
		tel,
		postalCode,
		streetName,
		town,
		country_id,
		contactPerson,
		importerID
	) {
		var url = serverURL + 'importerExporter/importerExporter';
		var formData = {
			name: name,
			email: email,
			tel: tel,
			postalCode: postalCode,
			streetName: streetName,
			town: town,
			country_id: country_id,
			contactPerson: contactPerson,
			importerID: importerID
		};
		var async_status = true;
		controller.allPostRequest(url, formData, async_status, function(data, status) {
			controller.refreshExportersData();
		});
	},
