	effectWindowRights: function(docStatus) {
		$('.controls').html('');
		if (docStatus == draftID) {
			if (urlPage == 'mission') {
				$('.controls').append(
					"<button type='button' class='ui button save mission_only'><i class='save icon'></i>Save</button>"
				);
				$('.controls').append(
					"<button type='button' class='ui button teal mofa_only start_approve'>Submit for User/Mission <i class='arrow right icon'></i></button>"
				);
			}
			if (urlPage == 'mofa') {
				$('.controls').append(
					"<button type='button' style='display:none;' class='ui button teal mofa_only forward'>Approve <i class='arrow right icon'></i></button>"
				);
			}
		} else if (docStatus == completedID) {
			controller.disableForm(true);
			if (urlPage == 'mission') {
			}
			if (urlPage == 'mofa') {
				$('.controls').append(
					"<button type='button' style='display:none;' class='ui button print_note blue mofa_only'><i class='print icon'></i> Print Note </button>"
				);
				$('.controls').append(
					"<button type='button' style='display:none;' class='ui button print_form blue mofa_only'><i class='print icon'></i> Print Form </button>"
				);
			}
		} else if (docStatus == inProgressID) {
			controller.disableForm(true);
			if (urlPage == 'mission') {
			}
			if (urlPage == 'mofa') {
				$('.controls').append(
					"<button type='button' style='display:none;' class='ui button teal mofa_only'>Approve <i class='arrow right icon'></i></button>"
				);
			}
			disableForm(true);
		} else if (docStatus == rejectedID) {
			disableForm(true);
		} else if (docStatus == ammendID) {
			$('.print').hide();
		}
		$('.print_note').on('click', function() {
			controller.printNote(this);
		});
		$('.print_form').on('click', function() {
			controller.printEntity(this);
		});
		$('#isDualCitizen').on('click', function() {
			if ($('#isDualCitizen').prop('checked') == true) {
				$('.otherCountry').show();
			} else {
				$('.otherCountry').hide();
			}
		});
	},
