	saveFormUploadDetails: function(formData, url, handleData) {
		$('.save').addClass('loading');
		$.ajax({
			url: url,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			type: 'post',
			data: formData,
			processData: false,
			contentType: false,
			success: function(data, textStatus, xhr) {
				handleData(data);
				if (xhr.status == 200) {
					controller.showToastMsg('Document Uploaded Successfully', '#1a5589');
				} else if (xhr.status == 201) {
					controller.showToastMsg('Error! Created', '#ff6666');
				} else if (xhr.status == 400) {
					controller.showToastMsg('Error! Fields are empty', '#ff6666');
				} else if (xhr.status == 401) {
					controller.showToastMsg('Error! Unauthorized', '#ff6666');
				} else if (xhr.status == 403) {
					controller.showToastMsg('Error! Forbidden', '#ff6666');
				} else if (xhr.status == 404) {
					controller.showToastMsg('Error! Not found', '#ff6666');
				} else if (xhr.status == 500) {
					controller.showToastMsg('Error! Duplicate, Record Exists', '#ff6666');
				}
				$('.save').removeClass('loading');
			},
			fail: function(xhr, textStatus) {
				if (xhr.status == 200) {
					controller.showToastMsg('Updated Successfully', '#1a5589');
				} else if (xhr.status == 201) {
					controller.showToastMsg('Error! Created' + errorMsg, '#ff6666');
				} else if (xhr.status == 400) {
					var t = xhr.responseText;
					var obj = JSON.parse(t);
					var errorArr = obj.errors;
					var errorMsg = '';
					for (var i in errorArr) {
						errorMsg = errorMsg + '</br>' + errorArr[i].defaultMessage;
					}
					controller.showToastMsg('Error! Fields are empty' + errorMsg, '#ff6666');
				} else if (xhr.status == 401) {
					controller.showToastMsg('Error! Unauthorized' + errorMsg, '#ff6666');
				} else if (xhr.status == 403) {
					controller.showToastMsg('Error! Forbidden' + errorMsg, '#ff6666');
				} else if (xhr.status == 404) {
					controller.showToastMsg('Error! Not found' + errorMsg, '#ff6666');
				} else if (xhr.status == 500) {
					var errorMsg = xhr.responseJSON.message;
					controller.showToastMsg('Error!' + errorMsg, '#ff6666');
				}
				$('.save').removeClass('loading');
			},
			error: function(xhr, textStatus) {
				if (xhr.status == 200) {
					controller.showToastMsg('Updated Successfully', '#1a5589');
				} else if (xhr.status == 201) {
					controller.showToastMsg('Error! Created' + errorMsg, '#ff6666');
				} else if (xhr.status == 400) {
					controller.showToastMsg('Failed Updating Document', '#ff6666');
				} else if (xhr.status == 401) {
					controller.showToastMsg('Error! Unauthorized' + errorMsg, '#ff6666');
				} else if (xhr.status == 403) {
					controller.showToastMsg('Error! Forbidden' + errorMsg, '#ff6666');
				} else if (xhr.status == 404) {
					controller.showToastMsg('Error! Not found' + errorMsg, '#ff6666');
				} else if (xhr.status == 500) {
					var errorMsg = xhr.responseJSON.message;
					controller.showToastMsg('Error!' + errorMsg, '#ff6666');
				}
				$('.save').removeClass('loading');
			}
		});
	},
	getPaymentPhytoInvoice: function(tableID, recordID, formTypeID, reponseObj) {
		var html = '';
		var url =
			serverURL + 'payment/getPaymentByFormTypeIDAndRecordID?recordID=' + recordID + '&formTypeID=' + formTypeID;
		$.ajax({
			url: url,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			success: function(data) {
				$('#makephytoApplicationpaymentbtn').hide();
				$('#submitphytoApplicationbtn').show();
				var requiredDocJSON = data;
				if (requiredDocJSON.length > 0) {
					var tableHTML = $(tableID);
					var visible = '';
					html = html + '<h2>Payments</h2>';
					html =
						html +
						"<table class='table table-striped'><tr><td style='color:#5ebd86'>Document Number</td><td style='color:#5ebd86'>Description</td><td style='color:#5ebd86'>Total Amount</td><td style='color:#09a04b'>Payment Status</td><td style='color:#09a04b'>Action</td></tr>";
					var num = 0;
					var paid;
					try {
						for (var i = 0; i < requiredDocJSON.length; i++) {
							if (requiredDocJSON[i].isPaid == true || requiredDocJSON[i].isPaid == 'true') {
								var visibility = "style='visibility: hidden;'";
								paid = 'Paid';
							} else {
								var visibility = "style='visibility: visible;'";
								paid = 'Not Paid';
							}
							if (recordID == requiredDocJSON[i]['record_id']) {
								html =
									html +
									'<tr><td>' +
									requiredDocJSON[i]['documentNumber'] +
									'</td><td>' +
									requiredDocJSON[i]['description'] +
									"</td><td><i style='color:green;' class='fa fa-money' style='margin-right:4px'> </i> MZN :" +
									requiredDocJSON[i]['amount'] +
									"</td><td style='color:#09a04b'>" +
									paid +
									'</td>';
								html = html + '</td><td ' + visibility + '>';
								html =
									html +
									"<input type='button' id='payImporterRegistrfation'  class='btn btn-success' onclick='paymentButton(" +
									recordID +
									");' value='Pay' style='backgound-color: yellow; color: white'>";
								html =
									html +
									"<input type='button' id='payImporterRegistrationd'  class='btn btn-info' onclick='postPayPayments(" +
									requiredDocJSON[i]['payment_id'] +
									");' value='On Account' style='backgound-color: yellow; color: white'>";
								html =
									html +
									"<input type='button' id='payImpdorterRegistration'  class='btn btn-success' onclick='refreshCrudPayments();' value='Refresh' style='backgound-color: yellow; color: white'></td>";
							} else {
								num++;
								html =
									html +
									'<tr><td>' +
									num +
									'. ' +
									requiredDocJSON[i]['documentNumber'] +
									'</td><td>' +
									requiredDocJSON[i]['description'] +
									'</td><td>MZN' +
									requiredDocJSON[i]['amount'] +
									'</td></td><td></td>';
								html = html + '</td><td>';
								html = html + '<tr></tr>';
							}
						}
					} catch (error) {}
					html = html + '</table>';
					tableHTML.html(html);
					reponseObj(html);
				} else {
					var tableHTML = $(tableID);
					tableHTML.html('');
					html = html + '</table>';
					tableHTML.html(html);
					reponseObj(html);
				}
			},
			fail: function() {},
			error: function(XMLHttpRequest, textStatus, errorThrown) {}
		});
	},

