	donwloadAttachment: function(x, e) {
		$('.modal.fade.eporterPaymentdocument').modal('show');
		$('#donwloadAttachment').html('Attachment Preview Loading.. Please Wait');
		for (var key in x) {
			if (x.hasOwnProperty(key)) {
				if (key == 'docStatus') {
					$('#' + key + '_name').val(x[key].name);
				}
				$('#' + key).val(x[key]);
			} else {
				$('#' + key).val(x[key]);
			}
		}
		var imageURL = serverURL + 'paymentDocument/downloadFile/' + x.name;
		$('#donwloadAttachment').html('Attachment Preview Loading.. Please Wait');
		controller.getFile(imageURL, function(response) {
			var path = x.path;
			var ext = path.split('.').pop();
			if (ext == 'pdf') {
				PDFObject.embed(response, '#donwloadAttachment');
			} else {
				$('#donwloadAttachment').html(
					"<img style='width:100%;min-height: 500px; height:100%;' src='" + response + "'>"
				);
			}
		});
		$('.delete').show();
	},

