	PrintTableInvoicePdf: function(recordID) {
		document.getElementById('PrintTableInvoicePdf').addEventListener('click', function() {
			var invoiceContainer = document.querySelector('.invoice-container');

			html2canvas(invoiceContainer).then(function(canvas) {
				var pdf = new jsPDF();
				var imgData = canvas.toDataURL('image/png');
				pdf.addImage(imgData, 'PNG', 0, 0, pdf.internal.pageSize.getWidth(), pdf.internal.pageSize.getHeight());
				pdf.save('invoice.pdf');
			});
		});
	},
	PrintTableInvoice: function(recordID) {
		var url = serverURL + 'payment/getPaymentByExporter?exporterID=' + recordID;
		$.ajax({
			url: url,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			success: function(data) {
				var total = data[0].amount;
				var formattedTotal = total.toLocaleString();
				var totalAmount = data.reduce((total, payment) => total + payment.amount, 0);

				var invoiceHtml = `<style>
                            body {
                                font-family: Arial, sans-serif;
                                margin: 0;
                                padding: 0;
                            }
                            .invoice-container {
                                max-width: 800px;
                                padding: 20px;
                                border: 1px solid #ccc;
                                box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
                                background-color: #fff;
                            }
                            .invoice-header {
                                text-align: center;
                                margin-bottom: 20px;
                            }
                            .invoice-title {
                                font-size: 24px;
                                color: #333;
                                margin-bottom: 10px;
                            }
                            .invoice-details {
                                margin-bottom: 20px;
                            }
                            .invoice-details p {
                                margin: 5px 0;
                            }
                            table {
                                width: 100%;
                                border-collapse: collapse;
                                margin-bottom: 20px;
                            }
                            th, td {
                                padding: 10px;
                                border-bottom: 1px solid #ccc;
                                text-align: left;
                            }
                            th {
                                background-color: #f5f5f5;
                            }
                            .invoice-total {
                                text-align: right;
                            }
                            .invoice-status {
                                text-align: right;
                            }
                            .paid {
                                color: green;
                            }
                            .not-paid {
                                color: red;
                            }
                        </style>
                        <div class="invoice-container_section">
                        <input type='button' id='PrintTableInvoicePdf'  class='btn btn-warning' onclick='controller.PrintTableInvoicePdf();' value='Generate PDF' style='backgound-color: yellow; color: white;'>
                        <div class="invoice-container">
                        <div class="invoice-header">
                            <h2 class="invoice-title">Payment Invoice</h2>
                        </div>
                        <div class="invoice-details">
                            <div class="company-details">
                                <p style="display: inline-block;">Company Name: ${data[0].user.company.name}</p>
                                <img src="img/eaalogo.png" alt="Company Logo" style="width: 80px; height: auto; float: right;">
                            </div>
                            <p>Total Amount MZN : ${formattedTotal}</p>
                            <p>Document Number: ${data[0].documentNumber}</p>
                            <p>Invoice Number: ${data[0].rPnref}</p>
                            <p>Payment Date: ${data[0].paymentDate}</p>
                        </div>
                        <table>
                            <tr>
                                <th>Description</th>
                                <th>Amount</th>
                            </tr>
                            ${data
								.map(
									(payment) => `
                                <tr>
                                    <td>${payment.description}</td>
                                    <td>${payment.amount}</td>
                                </tr>
                            `
								)
								.join('')}
                        </table>
                        <div class="invoice-total">
                            <p>Total Amount: ${formattedTotal}</p>
                        </div>
                        <div class="invoice-status">
                            <p class="${data[0].isPaid ? 'paid' : 'not-paid'}">Status: ${data[0].isPaid
					? 'Paid'
					: 'Not Paid'}</p>
                        </div>
                    </div>
                    </div>
                    `;

				// Append or insert 'invoiceHtml' into your desired element in the DOM

				// Inject the invoice HTML into the DOM element
				var invoiceContainer = document.getElementById('crud_section_payments_section');
				invoiceContainer.innerHTML = invoiceHtml;
			},
			fail: function() {},
			error: function(XMLHttpRequest, textStatus, errorThrown) {}
		});
		var html = '';
	},

	PrintTable: function() {
		var printWindow = window.open('', '_blank', 'height=600,width=800');
		printWindow.document.write('<html><head><title>Payment Details</title>');
		var table_style = document.getElementById('table_style').innerHTML;
		printWindow.document.write('<style type = "text/css">');
		printWindow.document.write(table_style);
		printWindow.document.write('</style>');
		printWindow.document.write('</head>');
		printWindow.document.write('<body>');
		var divContents = document.getElementById('invoiceprintout').innerHTML;
		printWindow.document.write(divContents);
		printWindow.document.write('</body>');
		printWindow.document.write('</html>');
		printWindow.print();
		printWindow.document.close();
	},
