	loadCommodities() {
		if (commoditiesArray.length > 0) {
			var option_ = '';
			option_ += "<option selected value=''>-Select Option-</option>";
			option_ += controller.loadSelect(commoditiesArray, 'products_id', 'name', '');
			$('#products_id').html(option_);
		} else {
			var url_p = serverURL + 'product/productApprovedList';
			var pageSize = 200; // Number of records to fetch in each batch
			var currentPage = 0; // The current page number
			var isFetching = false; // Flag to prevent concurrent fetches
			// Hide the select element while loading
			// selectElement.style.display = 'none';
			var option_a = '';

			function fetchRecords() {
				if (isFetching) {
					return; // Avoid concurrent fetches
				}
				isFetching = true;
				var url = url_p + '?pageNo=' + currentPage + '&pageSize=' + pageSize;
				controller.getAuthRequest(url, true, function(data, status) {
					isFetching = false;
					if (data.length > 0) {
						commoditiesArray = commoditiesArray.concat(data);
						option_a += "<option selected value=''>-Select Option-</option>";
						option_a += controller.loadSelect(commoditiesArray, 'products_id', 'name', '');
						$('#products_id').html(option_a);
						currentPage++;
						fetchRecords();
					}
				});
			}

			// Start fetching records from the first page (page 0)
			fetchRecords();
		}
	},

	loadEditCommodities() {
		if (commoditiesArray.length > 0) {
			var option_ = '';
			option_ += controller.loadSelect(commoditiesArray, 'products_id', 'name', '');
			$('#products_id').html(option_);
		} else {
			var url_p = serverURL + 'product/productApprovedList';
			var pageSize = 200; // Number of records to fetch in each batch
			var currentPage = 0; // The current page number
			var isFetching = false; // Flag to prevent concurrent fetches
			// Hide the select element while loading
			// selectElement.style.display = 'none';
			function fetchRecords() {
				if (isFetching) {
					return; // Avoid concurrent fetches
				}
				isFetching = true;
				var url = url_p + '?pageNo=' + currentPage + '&pageSize=' + pageSize;
				controller.getAuthRequest(url, true, function(data, status) {
					isFetching = false;

					if (data.length > 0) {
						commoditiesArray = commoditiesArray.concat(data);
						var option_a = '';
						option_a += controller.loadSelect(commoditiesArray, 'products_id', 'name', '');
						$('#products_id').html(option_a);
						currentPage++;
						fetchRecords();
					}
				});
			}

			// Start fetching records from the first page (page 0)
			fetchRecords();
		}
	},

	pesaflowGetByRecordIdAndFormTypeID: function(recordID, formTypeID, success_url) {
		var url =
			serverURL + 'payment/getPaymentByFormTypeIDAndRecordID?recordID=' + recordID + '&formTypeID=' + formTypeID;
		controller.requestWithToken(url, function(data, status) {
			if (data.length > 0) {
				var payment_id = data[0].payment_id;
			} else {
				var tableHTML = $('.pesaflowWindowSection');
				tableHTML.html('Sorry! No Payment has been Created for this record, Please Contact Admin !');
			}
			var url_ =
				serverURL +
				'api/mpesa/requestPesaflow?recordID=' +
				payment_id +
				'&successURL=' +
				callback_url +
				'' +
				success_url;
			controller.requestWithToken(url_, function(data, status) {
				var tableHTML = $('.pesaflowWindowSection');
				tableHTML.html('');
				tableHTML.html('Loading.....Please wait!!!');
				var response = data.data;
				if (response) {
					var tableHTML = $('.pesaflowWindowSection');
					tableHTML.html(response);
				} else {
					var tableHTML = $('.pesaflowWindowSection');
					tableHTML.html('Sorry! No Payment has been created for this record,Please Contact Admin !');
				}
			});
		});
		// controller.checkPesaflowPaymentStatus(recordID, formTypeID);
	},

