	getRequiredDocument: function(formType_id, callbackFunc) {
		var listUrl = serverURL + 'requiredDocument/requiredDocumentList?pageNo=0&pageSize=1000';
		$.ajax({
			url: listUrl,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			success: function(data) {
				var jsonData = data;
				var arrayIds = [];
				for (var i = 0; i < jsonData.length; i++) {
					if (jsonData[i]['formType']['formType_id'] == formType_id) {
						arrayIds.push(jsonData[i]);
					}
				}
				callbackFunc(arrayIds);
			},
			fail: function() {
				$('#blinder').hide();
			},
			error: function(XMLHttpRequest, textStatus, errorThrown) {
				$('#blinder').hide();
			}
		});
	},
