	editglobalDocument: function(ID, e, saveobj) {
		document.getElementById('name').value = null;
		document.getElementById('name').value = '';
		document.getElementById('description').value = null;
		document.getElementById('filename').value = null;
		$('.reportAttachmentUpload').modal('show');
		document.getElementById('confirmUploadBtn').style = 'display:none;';
		$('#confirmUploadBtn').hide();
		$('#confirmUpdateUploadBtn').hide();
		var name = $('#name').val();
		var description = $('#description').val();
		var file_data = $('input[name="filename"]')[0].files;
		$('input[type=file]').on('change', function() {
			var filelenght = file_data.length;
			if (filelenght === 0) {
			} else {
				$('#confirmUpdateUploadBtn').show();
				document.getElementById('confirmUpdateUploadBtn').innerHTML = 'Updating Document Please Wait ...';
				document.getElementById('confirmUpdateUploadBtn').disabled = true;
				var url =
					serverURL +
					'globalDocument/updateGlobalDocument?description=' +
					description +
					'&documentUploadType_id=0&globalDocument_id=' +
					ID +
					'&name=' +
					name +
					'&recordId=' +
					saveobj.recordId +
					'&tableRegisterId=' +
					saveobj.tableRegister.tableRegister_id;
				var formData2 = new FormData();
				formData2.append('file', file_data[0]);
				$.ajax({
					url: url,
					headers: {
						Authorization: userObj.tokenType + ' ' + userObj.accessToken
					},
					async: true,
					type: 'post',
					data: formData2,
					processData: false,
					contentType: false,
					success: function(data, textStatus, xhr) {
						if (xhr.status == 200) {
							$('.reportAttachmentUpload').modal('hide');
							$('#confirmUpdateUploadBtn').hide();
							document.getElementById('name').value = null;
							document.getElementById('description').value = null;
							document.getElementById('filename').value = null;
							controller.showToastMsg('Document Updated Successfully', '#1a5589');
							document.getElementById('confirmUpdateUploadBtn').innerHTML = 'Update Document';
							document.getElementById('confirmUpdateUploadBtn').disabled = false;
							controller.refreshCrudTables(this);
						}
					},
					fail: function(xhr, textStatus) {
						controller.showToastMsg('Not uploaded', '#ff6666');
						document.getElementById('confirmUpdateUploadBtn').innerHTML = 'Update Document';
						document.getElementById('confirmUpdateUploadBtn').disabled = false;
						$('.reportAttachmentUpload').modal('hide');
						controller.refreshCrudTables(this);
					},
					error: function(xhr, textStatus) {
						controller.showToastMsg('Not uploaded', '#ff6666');
						document.getElementById('confirmUpdateUploadBtn').innerHTML = 'Update Document';
						document.getElementById('confirmUpdateUploadBtn').disabled = false;
						$('.reportAttachmentUpload').modal('hide');
						controller.refreshCrudTables(this);
					}
				});
			}
		});
	},
