	getCountriesView: function() {
		var url = serverURL + 'countries/countryList?pageNo=0&pageSize=10000000';
		controller.requestWithToken(url, function(data, status) {
			var option = '';
			$('#country_id').html();
			for (var i = 0; i < data.length; i++) {
				option += '<option selected value=' + data[i].country_id + '>' + data[i].name + '</option>';
			}
		});
	},
