	checkCondition: function(formName) {
		if (formName == 'pip_application') {
			if (
				$('#country_of_origin_id').val() &&
				$('#import_purposeid').val() &&
				$('#product_form_id').val() &&
				$('#products_id').val()
			) {
				var country = $('#country_of_origin_id').val();
				var importpurpose = $('#import_purposeid').val();
				var productform = $('#product_form_id').val();
				var products = $('#products_id').val();
				var url =
					serverURL +
					'importRequirement/getImportRequirements?country_id=' +
					country +
					'&import_purpose_id=' +
					importpurpose +
					'&product_form_id=' +
					productform +
					'&products_id=' +
					products +
					'';
				controller.getAuthRequest(url, true, function(data, status) {
					if (status) {
						var option = $('<option></option>');
						option.attr('value', data.importCondition.import_condition_id);
						option.text(data.importCondition.name);
						$('#import_condition_id').html();
						$('#import_condition_id').html(option);
						$('#description').val(data.description);
					} else {
						controller.showToastMsg(data.responseJSON.data, '#ff6666');
					}
				});
			} else {
			}
		}
	},
