					var products_id = $('#' + val).val();
					// var countryid = allFormObj["selected"]["countryOfDestination"]["country_id"];
					var url = serverURL + 'productForm/findByProduct?pageNo=0&pageSize=1000&productID=' + products_id;
					// var url = serverURL + 'exportRequirement/findProductFormByExportRequiremntCountry?countryId=' + countryid + '&productId=' + products_id + '';
