	getPIPApplicationByCompany: function(company_id, formName) {
		var url = serverURL + 'pipApplication/getPIPApplicationByCompany?companyID=' + company_id + '';
		var option = '';
		controller.getAuthRequest(url, true, function(data, status) {
			var option = '';
			option += '<option>-Select Import Permit-</option>';
			$('#farms').html();
			for (var i = 0; i < data.length; i++) {
				option += '<option value=' + data[i].pipApplicationID + '>' + data[i].pipApplicationID + '</option>';
				$('#pip_application_id').html(option);
			}
		});
	},
