	populateInspectionCheclist: function(recordID, data) {
		$('.modal.fade.inspectionphytoformformmodal').modal('show');
		var html = '';
		$.ajax({
			url: serverURL + 'inspectionLine/getInspectionLineByInspectionHeaderID?inspectionHeaderID=' + recordID,
			headers: {
				Authorization: userObj.tokenType + ' ' + userObj.accessToken
			},
			async: true,
			success: function(data) {
				var requiredQuestions = data;
				var jsonData = data;
				var documentTypesUploaded = [];
				var tableHTML = $('#inspectionphytoform');
				var num = 0;
				var tmpCat = '';
				html = html + "<table class='table table-striped'>";
				html = html + '</table>';
				for (var i = 0; i < requiredQuestions.length; i++) {
					for (var j = 0; j < jsonData.length; j++) {
						var t = jsonData[j];
						if (jsonData[j]['inspectionLineID'] == requiredQuestions[i]['inspectionLineID']) {
							html = html + '<div class="three fields">';
							html = html + '<div class="field">';
							html = html + '<div class="field" id="survey_label">';
							html = html + '<label>Product</label>';
							html =
								html +
								'<label style="color:black;">' +
								requiredQuestions[i]['exportRequirement']['products']['name'] +
								'</label>';
							html =
								html +
								'<input type="text" style="display:none" id=' +
								requiredQuestions[i]['inspectionLineID'] +
								' value="' +
								requiredQuestions[i]['inspectionLineID'] +
								'">';
							html =
								html +
								'<input type="text" style="display:none" id="inspectionHeaderID" value="' +
								recordID +
								'">';
							html = html + '</div>';
							html = html + '</div>';
							html = html + '<div class="field">';
							html = html + '<label>Requirement</label>';
							html =
								html +
								'<label style="color:black;">' +
								requiredQuestions[i]['exportRequirement']['description'] +
								'</label>';
							html =
								html +
								'<input type="text" style="display:none" id="export_requirement_id" value="' +
								requiredQuestions[i]['exportRequirement']['export_requirement_id'] +
								'">';
							html = html + '</div>';
							html = html + '<div class="field">';
							html = html + '<label>Observations</label>';
							html =
								html +
								'<select onchange=controller.getobservations("' +
								requiredQuestions[i]['status'] +
								'_remarks' +
								'") id="status" class="ui fluid dropdown">';
							html = html + '<option value="" selected>-Pending-</option>';
							html = html + '<option value="Yes">Yes</option>';
							html = html + '<option value="No">No</option>';
							html = html + '</select>';
							html = html + '</div>';
							html = html + '</div>';
							html = html + '<div class="field">';
							html = html + '<div class="field">';
							html = html + '<label style="color:black;">Remarks</label>';
							html =
								html +
								'<textarea id="remarks"  class="form-control" style=" min-width:500px; max-width:100%;min-height:50px;height:100%;width:100%;" ></textarea>';
							html = html + '</div>';
							html = html + '</div>';
						}
					}
				}
				tableHTML.html(html);
				$('#inspectionphytoform').show();
			},
			fail: function() {
				$('#blinder').hide();
			},
			error: function(XMLHttpRequest, textStatus, errorThrown) {
				$('#blinder').hide();
			}
		});
	},
