	loadOptionsAfresh: function(selectID, obj_name, val_name) {
		var options = '';
		if (setupObj[obj_name].length == 0) {
			options += '<option>No Value</option>';
		} else {
			for (i in setupObj[obj_name]) {
				if (setupObj[obj_name][i]['name']) {
					options +=
						"<option value='" +
						setupObj[obj_name][i][val_name] +
						"'>'" +
						setupObj[obj_name][i]['name'] +
						"'</option>";
				} else if (setupObj[obj_name][i]['documentNumber']) {
					options +=
						"<option value='" +
						setupObj[obj_name][i][val_name] +
						"'>'" +
						setupObj[obj_name][i]['documentNumber'] +
						"'</option>";
				}
			}
		}
		$('#' + selectID + '').html(options);
	},
	assignPostRelease: function(date) {
		var inspector = document.getElementById('nextInspector').value;
		var data = SelectedData[SelectedData.length - 1];
		var url = serverURL + 'assignInspection/assignInspection';
		var async_status = true;
		if (date) {
			var nextDate = date;
			for (i in data) {
				data[i].consignment_inspection_request_id = data[i].consignmentInspectionRequestID;
				data[i].proposedInspectionDate = nextDate;
				data[i].users_id = inspector;
			}
		} else {
			for (i in data) {
				data[i].consignment_inspection_request_id = data[i].consignmentInspectionRequestID;
				data[i].proposedInspectionDate = data[i].preferedInspectionDate;
				data[i].users_id = inspector;
			}
		}
		controller.allPostRequest(url, data, async_status, function(data, status) {
			if (data) {
				controller.showToastMsg('Assigned Successfuly', '#1a5589');
			}
			SelectedData = [];
		});
	},




	assignPrinting: function(doc) {
		var inspector = document.getElementById('nextInspector').value;
		var data = SelectedData[SelectedData.length - 1];
		var url = serverURL + 'assignAuthorisation/assignAuthorisation';
		var async_status = true;
		if (doc == 'Phyto') {
			for (i in data) {
				data[i].exporterConsignmentID = data[i].exporterConsignmentID;
				data[i].pip = false;
				data[i].phyto = true;
				data[i].users_id = inspector;
				data[i].assigned = true;
			}
		} else if (doc == 'Pip') {
			for (i in data) {
				data[i].pip_application_id = data[i].pipApplicationID;
				data[i].pip = true;
				data[i].phyto = false;
				data[i].users_id = inspector;
				data[i].assigned = true;
			}
		} else if ((doc = 'importReleaseForm')) {
			for (i in data) {
				data[i].consignment_inspection_request_id = data[i].consignmentInspectionRequestID;
				data[i].pip = false;
				data[i].phyto = false;
				data[i].users_id = inspector;
				data[i].assigned = true;
			}
		}
		controller.assignPrintingFunc(url, data, async_status, function(data, status) {
			SelectedData = [];
		});
	},










