	signPrint: function(doc) {
		var data = SelectedData[SelectedData.length - 1];
		for (i in data) {
			ids.push({
				assignAuthorityID: data[i].assign_authorisation_id
			});
		}
		var async_status = true;
		var url = serverURL + 'print/' + doc + '';
		controller.postRequest(url, ids, async_status, function(data, status) {
			if (data.status == 500) {
				controller.showToastMsg('Failed Printing Document, Try again...', '#ff6666');
				controller.refreshCrudTables();
			} else if (data != null) {
				var binary = '';
				var responseTextLen = data.length;
				for (i = 0; i < responseTextLen; i++) {
					binary += String.fromCharCode(data.charCodeAt(i) & 255);
				}
				var base64 = btoa(binary);

				function downloadPDF() {
					const linkSource = `data:application/pdf;base64,${base64}`;
					const downloadLink = document.createElement('a');
					const fileName = 'Application.pdf';
					downloadLink.href = linkSource;
					downloadLink.download = fileName;
					downloadLink.click();
				}
				downloadPDF();
				controller.refreshCrudTables();
				/**
                 * Display a base64 URL inside an iframe in another window.
                 */
			} else {
				controller.showToastMsg('Kindly Select Document to print', '#ff6666');
			}
			ids = [];
			SelectedData = [];
		});
	},
	getInspectors: function(tableRegisterID) {
		var inspectorList = '';
		var activity = [];
		var approvers = [];
		var users = [];

		// Add default option with the selected attribute
		inspectorList += "<option selected value=''>-Select Inspector-</option>";

		url1 = serverURL + 'workflowActivity/getWorkFlowActivityByUser';
		var async_status = true;
		controller.getAuthRequest(url1, async_status, function(data, status) {
			try {
				for (let i = 0; i < data.length; i++) {
					const element = data[i];
					activity.push(data[i]);

					var nodeID = data[i].wFNode.wFNode_id;
					var users_id = data[i].initiator_id.users_id;
					var url =
						serverURL +
						'workflowActivity/getNextApproversList?nodeId=' +
						nodeID +
						'&initaitor_id=' +
						users_id +
						'&tableRegisterId=' +
						tableRegisterID;
					var async_status = true;
					controller.getAuthRequest(url, async_status, function(data, status) {
						if (data.length > 0) {
							for (let i = 0; i < data.length; i++) {
								var duplicate = false;
								for (let j = 0; j < approvers.length; j++) {
									if (data[i].users_id == approvers[j].users_id) {
										duplicate = true;
										break;
									}
								}
								if (!duplicate) {
									approvers.push(data[i]);
									inspectorList +=
										'<option value=' +
										data[i].users_id +
										'>' +
										data[i].firstName +
										'   ' +
										data[i].lastName +
										'</option>';
									// $('.nextInspector').html(inspectorList);
								}
							}
						} else {
						}

						// Once all data is processed, set the options in the select element
						$('.nextInspector').html(inspectorList);
					});
				}
			} catch (error) {}
		});
	},
