	refreshCrudTables: function(formName = '') {
		if (formName == '') {
			for (i in allFormObj) {
				try {
					controller.renderCRUDTable(allFormObj[i], 'GET');
				} catch (e) {}
			}
		} else {
			controller.renderCRUDTable(allFormObj[formName], 'GET');
		}
	},
