	InspectionApprove: function(cell) {
		$('.recommend').html('Approving.. Please Wait');

		setTimeout(function() {
			$('.recommend').html('Recommend');
		}, 5000);

		if (cell.exporterConsignment === undefined) {
			var exporterConsignmentID = 0;
		} else {
			var exporterConsignmentID = cell.exporterConsignment.exporterConsignmentID;
		}
		if (cell.exporterFarm === undefined) {
			var exporterFarmID = 0;
		} else {
			var exporterFarmID = cell.exporterFarm.exporterFarmID;
		}
		if (cell.exporterFirm === undefined) {
			var exporterFirmID = 0;
		} else {
			var exporterFirmID = cell.exporterFirm.exporterFirmID;
		}
		if (cell.exporter === undefined) {
			var exporterID = 0;
		} else {
			var exporterID = cell.exporter.exporterID;
		}
		if (cell.exporterInspectionRequest === undefined) {
			var exporterInspectionRequestID = 0;
		} else {
			var exporterInspectionRequestID = cell.exporterInspectionRequest.exporterInspectionRequestID;
		}
		if (cell.exporterLowRiskCommodity === undefined) {
			var exporterLowRiskCommodityID = 0;
		} else {
			var exporterLowRiskCommodityID = cell.exporterLowRiskCommodity.exportLowRiskCommodityID;
		}
		if (cell.importer === undefined) {
			var importerID = 0;
		} else {
			var importerID = cell.importer.importerID;
		}
		if (cell.importerInspectionRequest === undefined) {
			var importerInspectionRequestID = 0;
		} else {
			var importerInspectionRequestID = cell.importerInspectionRequest.importerInspectionRequestID;
		}
		if (cell.pipApplication === undefined) {
			var pipApplicationID = 0;
		} else {
			var pipApplicationID = cell.pipApplication.pipApplicationID;
		}
		if (cell.quarantineFacility === undefined) {
			var quarantineFacilityID = 0;
		} else {
			var quarantineFacilityID = cell.quarantineFacility.quarantineFacilityID;
		}
		var formJson = {
			companyID: cell.company.company_id,
			exporterConsignmentID: exporterConsignmentID,
			exporterFarmID: exporterFarmID,
			exporterFirmID: exporterFirmID,
			exporterID: exporterID,
			exporterInspectionRequestID: exporterInspectionRequestID,
			exporterLowRiskCommodityID: exporterLowRiskCommodityID,
			importerID: importerID,
			importerInspectionRequestID: importerInspectionRequestID,
			inspectionHeaderID: cell.inspectionHeaderID,
			inspectionTypeID: cell.inspectionType.inspectionTypeID,
			lowRiskCommodity: cell.isLowRiskCommodity,
			passedInsp: true,
			pipApplicationID: pipApplicationID,
			quarantineFacilityID: quarantineFacilityID,
			validUntil: ''
		};

		var url = serverURL + 'inspectionHeader/updateInspectionHeader';
		var async_status = true;
		controller.inspectionChecklistPostRequest(url, formJson, async_status, function(data, status) {
			if (data.statusText == 'error') {
				controller.showToastMsg('error!' + data.responseJSON.message + '', '#1a5589');
			} else {
				loadData();
				refresh();
			}
		});
	},

